        Semaphore { count: Mutex::new(count), cv: Condvar::new() }
    }
    fn acquire(&self) {
        let mut c = self.count.lock().unwrap();
        while *c == 0 { c = self.cv.wait(c).unwrap(); }
        *c -= 1;
    }
    fn release(&self) {
        let mut c = self.count.lock().unwrap();
        *c += 1;
        self.cv.notify_one();
    }
}

fn main() {
